CREATE DEFINER=`root`@`localhost` PROCEDURE `GetSumaUtilidad` (IN `fecha_ini` DATE, IN `fecha_fin` DATE, OUT `suma_utilidad` DECIMAL(10,2))   BEGIN
    SELECT SUM((JSON_EXTRACT(JSON_EXTRACT(v.productos, CONCAT('$[', n, '].precio')), '$') - p.precio_compra) * (REPLACE(JSON_EXTRACT(JSON_EXTRACT(v.productos, CONCAT('$[', n, '].cantidad')), '$'), '"', ''))/12) INTO suma_utilidad
    FROM ventas v
    INNER JOIN (
        SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL 
        SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13
    ) numbers ON n < JSON_LENGTH(v.productos)
    JOIN productos p ON REPLACE(JSON_EXTRACT(JSON_EXTRACT(v.productos, CONCAT('$[', n, '].id')), '$'), '"', '') = p.id
    WHERE DATE(v.fecha) BETWEEN fecha_ini AND fecha_fin;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `prc_clientes` ()   SELECT COUNT(*) AS clientes FROM `clientes`$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `prc_estado_ventas` ()   SELECT ventas.codigo, clientes.nombre, ventas.fecha, ventas.estado 
FROM ventas 
INNER JOIN clientes ON ventas.id_cliente = clientes.id
WHERE ventas.estado  = 0
ORDER BY  ventas.fecha DESC
LIMIT 20$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `prc_get_dashboard` ()   BEGIN
DECLARE totalproductos INT;
DECLARE totalclientes INT;
DECLARE totalVentasHoy FLOAT;
SET totalproductos = (SELECT COUNT(*) AS productos FROM `productos`);
SET totalclientes = (SELECT COUNT(*) AS clientes FROM `clientes`);
SET totalVentasHoy = (
    SELECT ROUND(SUM(p.importe), 2) AS total_hoy
    FROM (
        SELECT ventas.id, ventas.id_cliente, 
               REPLACE(JSON_EXTRACT(JSON_EXTRACT(ventas.productos, CONCAT('$[',n,'].id')), '$'), '"', '') AS id_producto,
               REPLACE(JSON_EXTRACT(JSON_EXTRACT(ventas.productos, CONCAT('$[',n,'].descripcion')), '$'), '"', '') AS descripcion,
               REPLACE(JSON_EXTRACT(JSON_EXTRACT(ventas.productos, CONCAT('$[',n,'].cantidad')), '$'), '"', '') AS cantidad,
               REPLACE(JSON_EXTRACT(JSON_EXTRACT(ventas.productos, CONCAT('$[',n,'].precio')), '$'), '"', '') AS precio_producto,
               REPLACE(JSON_EXTRACT(JSON_EXTRACT(ventas.productos, CONCAT('$[',n,'].total')), '$'), '"', '') AS importe
        FROM ventas
        INNER JOIN (
            SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13
        ) numbers
        WHERE n < JSON_LENGTH(ventas.productos)
    ) p
    INNER JOIN ventas ON p.id = ventas.id 
    INNER JOIN productos pr ON p.id_producto = pr.id 
    INNER JOIN clientes cl ON ventas.id_cliente = cl.id
    WHERE DATE(ventas.fecha) = CURDATE()
);
SELECT 
    IFNULL(totalproductos, 0) AS totalproductos,
    IFNULL(totalclientes, 0) AS totalclientes,
    IFNULL(round(totalVentasHoy), 0) AS totalVentasHoy;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `prc_get_utilidad` (IN `fecha_ini` DATE, IN `fecha_fin` DATE)   BEGIN
    SELECT v.id, 
           v.id_cliente,
           v.fecha,
           v.codigo,
           REPLACE(JSON_EXTRACT(JSON_EXTRACT(v.productos, CONCAT('$[', n, '].id')), '$'), '"', '') AS id_producto,
           REPLACE(JSON_EXTRACT(JSON_EXTRACT(v.productos, CONCAT('$[', n, '].descripcion')), '$'), '"', '') AS descripcion,
           REPLACE(JSON_EXTRACT(JSON_EXTRACT(v.productos, CONCAT('$[', n, '].cantidad')), '$'), '"', '') AS cantidad,
           REPLACE(JSON_EXTRACT(JSON_EXTRACT(v.productos, CONCAT('$[', n, '].precio')), '$'), '"', '') AS precio_producto,
           p.precio_compra,
           REPLACE(JSON_EXTRACT(JSON_EXTRACT(v.productos, CONCAT('$[', n, '].total')), '$'), '"', '') AS importe,
           (JSON_EXTRACT(JSON_EXTRACT(v.productos, CONCAT('$[', n, '].precio')), '$') - p.precio_compra) * (REPLACE(JSON_EXTRACT(JSON_EXTRACT(v.productos, CONCAT('$[', n, '].cantidad')), '$'), '"', ''))/12 AS utilidad_producto
    FROM ventas v
    INNER JOIN (
        SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL 
        SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9 UNION ALL SELECT 10 UNION ALL SELECT 11 UNION ALL SELECT 12 UNION ALL SELECT 13
    ) numbers ON n < JSON_LENGTH(v.productos)
    JOIN productos p ON REPLACE(JSON_EXTRACT(JSON_EXTRACT(v.productos, CONCAT('$[', n, '].id')), '$'), '"', '') = p.id
    WHERE DATE(v.fecha) BETWEEN fecha_ini AND fecha_fin;
END$$

